public class AuditFilter : IAsyncActionFilter
{
    public async Task OnActionExecutionAsync(ActionExecutingContext ctx, ActionExecutionDelegate next)
    {
        var executed = await next();                 // action + inner filters
        logger.LogInformation("{action} -> {status}", ctx.ActionDescriptor.DisplayName,
            (executed.Result as ObjectResult)?.StatusCode ?? 200);
    }
}
